from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
left = Motor(Port.C, Direction.COUNTERCLOCKWISE)
right = Motor(Port.D, Direction.CLOCKWISE)
front_aram_ = Motor(Port.E, Direction.CLOCKWISE)
good_wheels = DriveBase(left, right, 62.4, 142)


# The main program starts here.
good_wheels.use_gyro(True)
good_wheels.straight(45)
good_wheels.settings(straight_speed=10)
good_wheels.turn(-90)
good_wheels.settings(straight_speed=200)
good_wheels.straight(170)
good_wheels.settings(straight_speed=500)
front_aram_.run_angle(500, -50)
front_aram_.run_angle(500, 50)
good_wheels.straight(-100)
good_wheels.turn(90)
good_wheels.straight(385)
good_wheels.turn(-45)
front_aram_.run_angle(500, -150)
good_wheels.straight(-450)
